            {"모드", "Mods"},
            {"모드 ", "Mods: "},
            {"모드 zip", "Mod zip"},
            {"모드 기록 지우기", "Clear mod record"},
            {"모드 기록 파일이 아닙니다: ", "This is not a mod record file: "},
            {"모드 꺼짐", "Mods: Off"},
